\set ON_ERROR_STOP on
-- =============================================================================
-- FLUX TRANSACTIONNELS ACHATS & VENTES ODOO LOCAL : SIT TRANSMISSION SARL (TENANT #5)
-- Source : Odoo Local (http://192.168.1.200:8069), Base: SIT-NV
-- Date de génération : 2026-10-24 15:21:00
-- PRÉSERVE INTÉGRALEMENT LES PRODUITS, CLIENTS, FOURNISSEURS DU CLOUD VPS
-- ZÉRO SUPPRESSION (AUCUN DELETE FROM), INSERTIONS SANS DOUBLONS
-- =============================================================================
BEGIN;

-- -----------------------------------------------------------------------------
-- 1. POINT DE VENTE & DÉPÔTS (TENANT #5)
-- -----------------------------------------------------------------------------
VALUES (5, 5, 'SIT TRANSMISSION SARL', 'SIT TRANSMISSION SARL', TRUE, CURRENT_TIMESTAMP)
ON CONFLICT (id) DO UPDATE 
SET nom_point_de_vente = EXCLUDED.nom_point_de_vente,
    nom = EXCLUDED.nom,
    tenant_id = EXCLUDED.tenant_id;

SELECT setval('point_de_vente_id_seq', GREATEST((SELECT COALESCE(MAX(id), 1) FROM point_de_vente), 5));

SELECT 'SIT TRANSMISSION', 'WH', 'Siège / Dépôt Central Casablanca', 5, TRUE, CURRENT_TIMESTAMP
WHERE NOT EXISTS (SELECT 1 FROM depots WHERE description = 'WH' AND point_de_vente_id = 5);

SELECT 'DEP TACHAROUK', 'TAC', 'Magasin Tacharouk Casablanca', 5, TRUE, CURRENT_TIMESTAMP
WHERE NOT EXISTS (SELECT 1 FROM depots WHERE description = 'TAC' AND point_de_vente_id = 5);

SELECT 'DEPOT GARA', 'GARA', 'Dépôt Gara', 5, TRUE, CURRENT_TIMESTAMP
WHERE NOT EXISTS (SELECT 1 FROM depots WHERE description = 'GARA' AND point_de_vente_id = 5);

-- Partenaires par défaut en sécurité pour pièces sans partenaire Odoo
SELECT 'FOURNISSEUR DIVERS', 'Casablanca', 'Casablanca', 'Maroc', 5, TRUE, 'NATIONAL', 'MAD', CURRENT_TIMESTAMP
WHERE NOT EXISTS (SELECT 1 FROM fournisseurs WHERE raison_social = 'FOURNISSEUR DIVERS' AND point_de_vente_id = 5);

SELECT 'CLI-DIVERS', 'CLIENT DIVERS', 'CLIENT DIVERS', 5, TRUE, CURRENT_TIMESTAMP 
WHERE NOT EXISTS (SELECT 1 FROM clients WHERE code_client = 'CLI-DIVERS' AND point_de_vente_id = 5);

-- -----------------------------------------------------------------------------
-- 2. ACHATS FOURNISSEURS (TENANT #5)
-- -----------------------------------------------------------------------------
UPDATE lignes_commande lc
SET quantite_livree = COALESCE((
    SELECT SUM(ll.quantite_livree)
    FROM lignes_livraison ll
    JOIN livraisons l ON ll.livraison_id = l.id
    WHERE l.commande_id = lc.commande_id
      AND ll.produit_id = lc.produit_id
), 0)
WHERE lc.commande_id IN (SELECT id FROM commandes WHERE point_de_vente_id = 5);

UPDATE commandes c
SET statut_livraison = CASE
    WHEN (SELECT COALESCE(SUM(quantite_livree), 0) FROM lignes_commande WHERE commande_id = c.id) >= (SELECT COALESCE(SUM(quantite_commandee), 0) FROM lignes_commande WHERE commande_id = c.id) AND (SELECT COALESCE(SUM(quantite_commandee), 0) FROM lignes_commande WHERE commande_id = c.id) > 0 THEN 'LIVREE'
    WHEN (SELECT COALESCE(SUM(quantite_livree), 0) FROM lignes_commande WHERE commande_id = c.id) > 0 THEN 'PARTIELLE'
    ELSE 'EN_ATTENTE'
END,
date_livraison_reelle = CASE
    WHEN (SELECT COALESCE(SUM(quantite_livree), 0) FROM lignes_commande WHERE commande_id = c.id) >= (SELECT COALESCE(SUM(quantite_commandee), 0) FROM lignes_commande WHERE commande_id = c.id) THEN COALESCE(c.date_livraison_reelle, CURRENT_TIMESTAMP)
    ELSE c.date_livraison_reelle
END
WHERE c.point_de_vente_id = 5;
UPDATE factures_achat fa
SET statut = CASE
    WHEN COALESCE((SELECT SUM(rf.montant) FROM reglements_fournisseur rf WHERE rf.facture_achat_id = fa.id), 0.00) >= fa.montant_ttc AND fa.montant_ttc > 0 THEN 'PAYEE_TOTALEMENT'
    WHEN COALESCE((SELECT SUM(rf.montant) FROM reglements_fournisseur rf WHERE rf.facture_achat_id = fa.id), 0.00) > 0 THEN 'PAYEE_PARTIELLEMENT'
    ELSE fa.statut
END
WHERE fa.point_de_vente_id = 5;

-- -----------------------------------------------------------------------------
