UPDATE bons_livraison_client bl 
SET montant_total = COALESCE((SELECT SUM(lbl.montant_ligne) FROM lignes_bon_livraison_client lbl WHERE lbl.bon_livraison_client_id = bl.id), 0.00) 
WHERE bl.point_de_vente_id = 5;
